mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  p.yz = rot(time * 0.2) * p.yz;
  float shell = abs(length(p) - 1.2) - 0.08;
  float holes = dot(sin(p * 5.0), cos(p.zxy * 5.0)) - 0.3;
  float outer = max(shell, holes);
  float star = length(p) - (0.4 + 0.08 * sin(time * 4.0));
  return min(outer, star);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float starGlow = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    starGlow += 0.01 / (0.1 + length(ro + rd * t));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.03, 0.08) + starGlow * vec3(0.2, 0.6, 1.0) * (1.0 + bass);
  if (t < 7.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.0, 1.5, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 40.0);
    col += vec3(0.05, 0.1, 0.3) + diff * vec3(0.1, 0.4, 0.9) + spec * vec3(0.8, 0.9, 1.0);
  }
  ret = col;
}
